actions.new_string:
lines = text.splitlines()
if not lines:
    # Handle empty list items
    text = '\n'
else:
    text = lines[0] + '\n'
    prefix = ' ' * len(leading)
    for line in lines[1:]:
        if line:
            text += prefix + line + '\n'
        else:
            text += '\n'
return leading + text
